 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Find each rectangular U-like frame: a solid bottom and side walls,
    # with a single opening in the top. Fill its interior and project the
    # opening leftward on the row above the frame.
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            cells = []
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                y, x = stack.pop(); cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 5 and (ny,nx) not in seen:
                        seen.add((ny,nx)); stack.append((ny,nx))
            minr, maxr = min(y for y,x in cells), max(y for y,x in cells)
            minc, maxc = min(x for y,x in cells), max(x for y,x in cells)
            cs = {(y,x) for y,x in cells}
            if maxr-minr < 2 or maxc-minc < 2:
                continue
            gaps = [x for x in range(minc+1,maxc) if (minr,x) not in cs]
            if len(gaps) != 1:
                continue
            gap = gaps[0]
            for y in range(minr+1,maxr):
                for x in range(minc+1,maxc):
                    if (y,x) not in cs:
                        out[y][x] = 2
            if minr > 0:
                for x in range(gap+1):
                    if grid[minr-1][x] == 0:
                        out[minr-1][x] = 2
    return out

if __name__ == '__main__':
